mapper.select:
SELECT *
FROM execution_items
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0

SELECT *
FROM execution_items
WHERE user_id        = #{userId}
  AND is_deleted     = 0
  AND scheduled_date = #{scheduledDate}
ORDER BY order_index ASC, scheduled_start_at ASC, execution_item_id ASC

SELECT *
FROM execution_items
WHERE user_id        = #{userId}
  AND is_deleted     = 0
  AND scheduled_date BETWEEN #{startDate} AND #{endDate}
ORDER BY scheduled_date ASC, order_index ASC, scheduled_start_at ASC, execution_item_id ASC

SELECT *
FROM execution_items
WHERE user_id    = #{userId}
  AND is_deleted = 0
  AND (
        scheduled_date BETWEEN #{startDate} AND #{endDate}
     OR (scheduled_date IS NULL
         AND planning_start_date <= #{endDate}
         AND planning_end_date   >= #{startDate})
      )
ORDER BY scheduled_date IS NULL,
         scheduled_date ASC, order_index ASC, execution_item_id ASC

SELECT MAX(order_index)
FROM execution_items
WHERE user_id        = #{userId}
  AND is_deleted     = 0
  AND scheduled_date = #{scheduledDate}

mapper.update:
UPDATE execution_items
SET scheduled_date     = #{scheduledDate},
    scheduled_start_at = #{scheduledStartAt},
    scheduled_end_at   = #{scheduledEndAt},
    version            = version + 1
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0
  AND version           = #{version}

UPDATE execution_items
SET title = CASE WHEN #{title} IS NOT NULL THEN #{title} ELSE title END,
    expected_minutes = CASE WHEN #{expectedMinutes} IS NOT NULL THEN #{expectedMinutes} ELSE expected_minutes END,
    version = version + 1
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0
  AND version           = #{version}

UPDATE execution_items
SET status  = #{status},
    version = version + 1
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0
  AND version           = #{version}

UPDATE execution_items
SET status  = 'DONE',
    version = version + 1
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0
  AND version           = #{version}

UPDATE execution_items
SET is_deleted = 1,
    version    = version + 1
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
  AND is_deleted        = 0
  AND version           = #{version}

UPDATE execution_items
SET topic_id = #{topicId}
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}

UPDATE execution_items
SET course_id = #{courseId}
WHERE execution_item_id = #{executionItemId}
  AND user_id           = #{userId}
